pub async fn cas_observe_retained_slot(root: String, key: String, retention: Rc<CasSlotRetention>, filesystem: &Filesystem) -> std::result::Result<Rc<CasSlotProbe>, std::boxed::Box<dyn std::error::Error>> {
    Ok(match (*retention.clone()).clone() {
    CasSlotRetention::KeepAllGenerations => cas_observe_slot(root.clone(), key.clone(), filesystem).await?,
    CasSlotRetention::KeepGenerationWindow { window: _, .. } => cas_observe_window(root.clone(), key.clone(), filesystem).await?,
})
}

pub fn cas_window_head_unsettled(attempts: i64) -> Rc<CasUnreadableSlot> {
    Rc::new(CasUnreadableSlot::CasUnreadableObservationBoundExceeded {
    bound: attempts.clone(),
})
}

pub fn cas_head_as_readable(generation: i64, value: String) -> Rc<CasReadableSlot<String>> {
    Rc::new(CasReadableSlot::CasReadablePresent {
    version: Rc::new(CasSlotVersion {
    generation: generation.clone(),
    content: crate::std_content_hash::content_hash_of_value(value.clone()),
    value: value.clone(),
    _phantom: std::marker::PhantomData,
}),
})
}

pub fn cas_generation_unreadable(generation: i64, kind: FilesystemFailureKind) -> Rc<CasUnreadableSlot> {
    Rc::new(CasUnreadableSlot::CasUnreadableReadRefused {
    detail: v1_rt::concat(v1_rt::concat("generation ".to_string(), crate::std_integer::int_to_decimal_string(crate::std_durable_compare_and_set::cas_generation_count(generation))), v1_rt::concat(" unreadable:".to_string(), crate::extdeps_filesystem_filesystem_io::filesystem_failure_kind_name(kind))),
})
}

pub fn cas_generation_read_kind_unrecognized(generation: i64, observed: String) -> Rc<CasUnreadableSlot> {
    Rc::new(CasUnreadableSlot::CasUnreadableMalformed {
    detail: v1_rt::concat(v1_rt::concat("generation ".to_string(), crate::std_integer::int_to_decimal_string(crate::std_durable_compare_and_set::cas_generation_count(generation))), v1_rt::concat(" read failure kind unrecognized: ".to_string(), observed.clone())),
})
}

pub fn cas_probe_as_observation(probe: Rc<CasSlotProbe>) -> Rc<CasSlotObservation<String>> {
    match (*probe.clone()).clone() {
    CasSlotProbe::ProbedUnreadable { generation: g, kind: k, .. } => Rc::new(CasSlotObservation::CasObservedUnreadable {
    cause: cas_generation_unreadable(g.clone(), k.clone()),
}),
    CasSlotProbe::ProbedReadKindUnrecognized { generation: g, observed: o, .. } => Rc::new(CasSlotObservation::CasObservedUnreadable {
    cause: cas_generation_read_kind_unrecognized(g.clone(), o.clone()),
}),
    CasSlotProbe::ProbedAbsent => Rc::new(CasSlotObservation::CasObservedReadable {
    readable: Rc::new(CasReadableSlot::CasReadableAbsent),
}),
    CasSlotProbe::ProbedAbsenceUnestablished { cause: c, .. } => Rc::new(CasSlotObservation::CasObservedUnreadable {
    cause: cas_absence_unestablished(c.clone()),
}),
    CasSlotProbe::ProbedWindowHeadUnsettled { attempts: a, .. } => Rc::new(CasSlotObservation::CasObservedUnreadable {
    cause: cas_window_head_unsettled(a.clone()),
}),
    CasSlotProbe::ProbedHead { generation: h, value: v, .. } => Rc::new(CasSlotObservation::CasObservedReadable {
    readable: cas_head_as_readable(h.clone(), v.clone()),
}),
}
}

pub async fn observe_cas_slot_state_retained(root: String, key: String, retention: Rc<CasSlotRetention>, filesystem: &Filesystem) -> std::result::Result<Rc<CasSlotObservation<String>>, std::boxed::Box<dyn std::error::Error>> {
    Ok(if !cas_key_is_slot_addressable(key.clone()) {
        Rc::new(CasSlotObservation::CasObservedUnreadable {
    cause: Rc::new(CasUnreadableSlot::CasUnreadableReadRefused {
    detail: cas_key_not_slot_addressable_detail(),
}),
})
    } else {
        cas_probe_as_observation(cas_observe_retained_slot(root, key.clone(), retention, filesystem).await?)
    })
}

pub async fn observe_cas_slot_state(root: String, key: String, filesystem: &Filesystem) -> std::result::Result<Rc<CasSlotObservation<String>>, std::boxed::Box<dyn std::error::Error>> {
    Ok(observe_cas_slot_state_retained(root, key, Rc::new(CasSlotRetention::KeepAllGenerations), filesystem).await?)
}

pub async fn observe_cas_slot_state_windowed(root: String, key: String, window: CasGenerationWindow, filesystem: &Filesystem) -> std::result::Result<Rc<CasSlotObservation<String>>, std::boxed::Box<dyn std::error::Error>> {
    Ok(observe_cas_slot_state_retained(root, key, Rc::new(CasSlotRetention::KeepGenerationWindow {
    window: window.clone(),
}), filesystem).await?)
}

#[derive(Debug, Clone, PartialEq, serde::Serialize, serde::Deserialize)]
#[serde(tag = "_variant")]
pub enum CasNamedWindowVerify {
    NamedWindowHeadCurrent {
        observation: Rc<CasSlotObservation<NonEmptyStr>>,
    },
    NamedWindowHeadMoved {
        named_generation: CasGeneration,
    },
}

pub async fn cas_verify_named_window_head(root: String, key: String, generation: i64, filesystem: &Filesystem) -> std::result::Result<Rc<CasNamedWindowVerify>, std::boxed::Box<dyn std::error::Error>> {
    Ok(if !cas_key_is_slot_addressable(key.clone()) {
        Rc::new(CasNamedWindowVerify::NamedWindowHeadCurrent {
    observation: Rc::new(CasSlotObservation::CasObservedUnreadable {
    cause: Rc::new(CasUnreadableSlot::CasUnreadableReadRefused {
    detail: cas_key_not_slot_addressable_detail(),
}),
}),
})
    } else {
        match (*cas_read_generation(root.clone(), key.clone(), generation.clone(), filesystem).await?).clone() {
    CasGenerationRead::GenerationRefused { probe: p, .. } => Rc::new(CasNamedWindowVerify::NamedWindowHeadCurrent {
    observation: cas_probe_as_observation(p.clone()),
}),
    CasGenerationRead::GenerationAbsent => Rc::new(CasNamedWindowVerify::NamedWindowHeadCurrent {
    observation: cas_probe_as_observation(Rc::new(CasSlotProbe::ProbedAbsent)),
}),
    CasGenerationRead::GenerationPresent { content: c, .. } => match (*crate::std_durable_compare_and_set::cas_generation_successor(generation.clone())).clone() {
    CasGenerationSuccessor::CasSuccessorExhausted { head: _, .. } => Rc::new(CasNamedWindowVerify::NamedWindowHeadCurrent {
    observation: cas_probe_as_observation(Rc::new(CasSlotProbe::ProbedHead {
    generation: generation.clone(),
    value: c.clone(),
})),
}),
    CasGenerationSuccessor::CasSuccessorGeneration { generation: next, .. } => match (*cas_read_generation(root.clone(), key.clone(), next.clone(), filesystem).await?).clone() {
    CasGenerationRead::GenerationRefused { probe: p, .. } => Rc::new(CasNamedWindowVerify::NamedWindowHeadCurrent {
    observation: cas_probe_as_observation(p.clone()),
}),
    CasGenerationRead::GenerationAbsent => Rc::new(CasNamedWindowVerify::NamedWindowHeadCurrent {
    observation: cas_probe_as_observation(Rc::new(CasSlotProbe::ProbedHead {
    generation: generation.clone(),
    value: c.clone(),
})),
}),
    CasGenerationRead::GenerationPresent { content: _, .. } => Rc::new(CasNamedWindowVerify::NamedWindowHeadMoved {
    named_generation: generation.clone(),
}),
},
},
}
    })
}

pub fn cas_key_not_slot_addressable_detail() -> NonEmptyStr {
    thread_local! {
        static CACHED: NonEmptyStr = {
            serde_json::from_str("\"key is not slot-addressable: it carries a path separator\"")
                .expect("valid data definition")
        };
    }
    CACHED.with(|c: &NonEmptyStr| c.clone())
}

#[derive(Debug, Clone, PartialEq, serde::Serialize, serde::Deserialize)]
#[serde(tag = "_variant")]
pub enum CasGenerationPublication {
    DefaultAccessCreateOnly,
    OwnerOnlyCreateOnly,
    DeclaredModeCreateOnly {
        mode: Rc<FileMode>,
    },
}
impl CasGenerationPublication {
    pub fn mode(&self) -> Rc<FileMode> {
        match self {
            CasGenerationPublication::DefaultAccessCreateOnly => panic!("no mode on unit variant"),
            CasGenerationPublication::OwnerOnlyCreateOnly => panic!("no mode on unit variant"),
            CasGenerationPublication::DeclaredModeCreateOnly { mode: __val, .. } => __val.clone(),
        }
    }
}

#[derive(Debug, Clone, PartialEq, serde::Serialize)]
pub struct AdmittedCasPublication {
    root: NonEmptyStr,
    publication: Rc<CasGenerationPublication>,
    retention: Rc<CasSlotRetention>,
    attempt: Rc<CasAttempt<NonEmptyStr>>,
    target: CasGeneration,
}
impl AdmittedCasPublication {
    pub fn root(&self) -> NonEmptyStr {
        self.root.clone()
    }
    pub fn publication(&self) -> Rc<CasGenerationPublication> {
        self.publication.clone()
    }
    pub fn retention(&self) -> Rc<CasSlotRetention> {
        self.retention.clone()
    }
    pub fn attempt(&self) -> Rc<CasAttempt<NonEmptyStr>> {
        self.attempt.clone()
    }
    pub fn target(&self) -> CasGeneration {
        self.target.clone()
    }
}

pub async fn cas_commit_at(admitted: Rc<AdmittedCasPublication>, filesystem: &Filesystem) -> std::result::Result<Rc<CasOutcome<String>>, std::boxed::Box<dyn std::error::Error>> {
    let root = admitted.root();
let attempt = admitted.attempt();
let target = admitted.target();
let path = cas_file_slot_path(root.clone(), attempt.key.clone(), target.clone());
let content = attempt.proposed.clone();
Ok(match (*admitted.publication()).clone() {
    CasGenerationPublication::DefaultAccessCreateOnly => {
        let write = filesystem.write_create_new(path.clone(), content.clone()).await?;
match cas_create_refusal(attempt.clone(), crate::extdeps_filesystem_filesystem_io::filesystem_create_new(write.2.clone(), write.0.clone(), write.3.clone(), write.4.clone()), observe_cas_slot_state_retained(root.clone(), attempt.key.clone(), admitted.retention(), filesystem).await?) {
    Some(refusal) => refusal.clone(),
    std::option::Option::None => Rc::new(CasOutcome::CasCommitted {
    committed: Rc::new(CasSlotVersion {
    generation: target.clone(),
    content: attempt.proposed_content.clone(),
    value: attempt.proposed.clone(),
    _phantom: std::marker::PhantomData,
}),
}),
}
},
    CasGenerationPublication::DeclaredModeCreateOnly { mode: mode, .. } => {
        let write = filesystem.write_create_new_with_mode(path.clone(), content.clone(), crate::extdeps_access_posix::file_mode_bits(mode.clone())).await?;
match cas_create_refusal(attempt.clone(), crate::extdeps_filesystem_filesystem_io::filesystem_create_new(write.2.clone(), write.0.clone(), write.3.clone(), write.4.clone()), observe_cas_slot_state_retained(root.clone(), attempt.key.clone(), admitted.retention(), filesystem).await?) {
    Some(refusal) => refusal.clone(),
    std::option::Option::None => Rc::new(CasOutcome::CasCommitted {
    committed: Rc::new(CasSlotVersion {
    generation: target.clone(),
    content: attempt.proposed_content.clone(),
    value: attempt.proposed.clone(),
    _phantom: std::marker::PhantomData,
}),
}),
}
},
    CasGenerationPublication::OwnerOnlyCreateOnly => {
        let write = filesystem.write_owner_only(path.clone(), content.clone()).await?;
if write.0.clone() {
            Rc::new(CasOutcome::CasCommitted {
    committed: Rc::new(CasSlotVersion {
    generation: target.clone(),
    content: attempt.proposed_content.clone(),
    value: attempt.proposed.clone(),
    _phantom: std::marker::PhantomData,
}),
})
        } else {
            cas_owner_only_failed_publication(root.clone(), admitted.retention(), attempt.clone(), target.clone(), write.3.clone(), filesystem).await?
        }
},
})
}

pub fn cas_create_refusal(attempt: Rc<CasAttempt<String>>, created: Rc<FilesystemCreateNew>, post: Rc<CasSlotObservation<String>>) -> Option<Rc<CasOutcome<String>>> {
    match (*created.clone()).clone() {
    FilesystemCreateNew::FilesystemCreated { path: _, .. } => std::option::Option::None,
    FilesystemCreateNew::FilesystemCreateTargetOccupied { path: _, .. } => Some(cas_occupied_publication_outcome(attempt, post)),
    FilesystemCreateNew::FilesystemCreateRefused { kind: k, .. } => Some(cas_publication_refused(v1_rt::concat("the store refused publication: ".to_string(), crate::extdeps_filesystem_filesystem_io::filesystem_failure_kind_name(k.clone())))),
    FilesystemCreateNew::FilesystemCreateKindUnrecognized { observed: o, .. } => Some(cas_publication_refused(v1_rt::concat("the store refused publication with an unrecognized failure kind: ".to_string(), o.clone()))),
}
}

pub fn cas_occupied_publication_outcome(attempt: Rc<CasAttempt<String>>, post: Rc<CasSlotObservation<String>>) -> Rc<CasOutcome<String>> {
    match (*post.clone()).clone() {
    CasSlotObservation::CasObservedUnreadable { cause: c, .. } => Rc::new(CasOutcome::CasStoreRefused {
    cause: Rc::new(CasStoreFailure::CasSlotObservationRefused {
    cause: c.clone(),
}),
}),
    CasSlotObservation::CasObservedReadable { readable: r, .. } => match (*r.clone()).clone() {
    CasReadableSlot::CasReadablePresent { version: _, .. } => Rc::new(CasOutcome::CasPreconditionFailed {
    expected: attempt.expected.clone(),
    observed: r.clone(),
}),
    CasReadableSlot::CasReadableAbsent => cas_publication_refused("exclusive create reported occupancy and no readable generation was observed".to_string()),
},
}
}

pub async fn cas_owner_only_failed_publication(root: String, retention: Rc<CasSlotRetention>, attempt: Rc<CasAttempt<String>>, target: i64, detail: String, filesystem: &Filesystem) -> std::result::Result<Rc<CasOutcome<String>>, std::boxed::Box<dyn std::error::Error>> {
    let probe = cas_observe_retained_slot(root, attempt.key.clone(), retention, filesystem).await?;
Ok(match (*probe.clone()).clone() {
    CasSlotProbe::ProbedHead { generation: h, value: v, .. } => if (crate::std_durable_compare_and_set::cas_generation_count(h.clone()) >= crate::std_durable_compare_and_set::cas_generation_count(target)) {
        Rc::new(CasOutcome::CasPreconditionFailed {
    expected: attempt.expected.clone(),
    observed: cas_head_as_readable(h.clone(), v.clone()),
})
    } else {
        cas_publication_refused(detail.clone())
    },
    CasSlotProbe::ProbedAbsent => cas_publication_refused(detail.clone()),
    CasSlotProbe::ProbedAbsenceUnestablished { cause: c, .. } => Rc::new(CasOutcome::CasStoreRefused {
    cause: Rc::new(CasStoreFailure::CasSlotObservationRefused {
    cause: cas_absence_unestablished(c.clone()),
}),
}),
    CasSlotProbe::ProbedUnreadable { generation: g, kind: k, .. } => Rc::new(CasOutcome::CasStoreRefused {
    cause: Rc::new(CasStoreFailure::CasSlotObservationRefused {
    cause: cas_generation_unreadable(g.clone(), k.clone()),
}),
}),
    CasSlotProbe::ProbedReadKindUnrecognized { generation: g, observed: o, .. } => Rc::new(CasOutcome::CasStoreRefused {
    cause: Rc::new(CasStoreFailure::CasSlotObservationRefused {
    cause: cas_generation_read_kind_unrecognized(g.clone(), o.clone()),
}),
}),
    CasSlotProbe::ProbedWindowHeadUnsettled { attempts: a, .. } => Rc::new(CasOutcome::CasStoreRefused {
    cause: Rc::new(CasStoreFailure::CasSlotObservationRefused {
    cause: cas_window_head_unsettled(a.clone()),
}),
}),
})
}

pub fn cas_publication_refused(detail: String) -> Rc<CasOutcome<String>> {
    Rc::new(CasOutcome::CasStoreRefused {
    cause: Rc::new(CasStoreFailure::CasGenerationPublicationRefused {
    detail: detail.clone(),
}),
})
}

pub async fn cas_compare_and_set_outcome(root: String, publication: Rc<CasGenerationPublication>, retention: Rc<CasSlotRetention>, verified: Rc<VerifiedCasAttempt>, filesystem: &Filesystem) -> std::result::Result<Rc<CasOutcome<String>>, std::boxed::Box<dyn std::error::Error>> {
    let attempt = verified.attempt();
let probe = cas_observe_retained_slot(root.clone(), attempt.key.clone(), retention.clone(), filesystem).await?;
Ok(match (*probe.clone()).clone() {
    CasSlotProbe::ProbedUnreadable { generation: g, kind: k, .. } => Rc::new(CasOutcome::CasStoreRefused {
    cause: Rc::new(CasStoreFailure::CasSlotObservationRefused {
    cause: cas_generation_unreadable(g.clone(), k.clone()),
}),
}),
    CasSlotProbe::ProbedReadKindUnrecognized { generation: g, observed: o, .. } => Rc::new(CasOutcome::CasStoreRefused {
    cause: Rc::new(CasStoreFailure::CasSlotObservationRefused {
    cause: cas_generation_read_kind_unrecognized(g.clone(), o.clone()),
}),
}),
    CasSlotProbe::ProbedAbsenceUnestablished { cause: c, .. } => Rc::new(CasOutcome::CasStoreRefused {
    cause: Rc::new(CasStoreFailure::CasSlotObservationRefused {
    cause: cas_absence_unestablished(c.clone()),
}),
}),
    CasSlotProbe::ProbedWindowHeadUnsettled { attempts: a, .. } => Rc::new(CasOutcome::CasStoreRefused {
    cause: Rc::new(CasStoreFailure::CasSlotObservationRefused {
    cause: cas_window_head_unsettled(a.clone()),
}),
}),
    CasSlotProbe::ProbedAbsent => match (*attempt.expected.clone()).clone() {
    CasExpectation::ExpectSlotAbsent => cas_commit_at(Rc::new(AdmittedCasPublication {
    root: root.clone(),
    publication: publication.clone(),
    retention: retention.clone(),
    attempt: attempt.clone(),
    target: crate::std_durable_compare_and_set::cas_generation_first(),
}), filesystem).await?,
    CasExpectation::ExpectSlotGeneration { generation: _, .. } => Rc::new(CasOutcome::CasPreconditionFailed {
    expected: attempt.expected.clone(),
    observed: Rc::new(CasReadableSlot::CasReadableAbsent),
}),
},
    CasSlotProbe::ProbedHead { generation: h, value: v, .. } => match (*attempt.expected.clone()).clone() {
    CasExpectation::ExpectSlotAbsent => Rc::new(CasOutcome::CasPreconditionFailed {
    expected: attempt.expected.clone(),
    observed: cas_head_as_readable(h.clone(), v.clone()),
}),
    CasExpectation::ExpectSlotGeneration { generation: g, .. } => if (crate::std_durable_compare_and_set::cas_generation_count(g.clone()) == crate::std_durable_compare_and_set::cas_generation_count(h.clone())) {
        match (*crate::std_durable_compare_and_set::cas_generation_successor(h.clone())).clone() {
    CasGenerationSuccessor::CasSuccessorExhausted { head: last, .. } => crate::std_durable_compare_and_set::cas_generation_exhausted(last.clone()),
    CasGenerationSuccessor::CasSuccessorGeneration { generation: next, .. } => cas_commit_at(Rc::new(AdmittedCasPublication {
    root: root.clone(),
    publication: publication.clone(),
    retention: retention.clone(),
    attempt: attempt.clone(),
    target: next.clone(),
}), filesystem).await?,
}
    } else {
        Rc::new(CasOutcome::CasPreconditionFailed {
    expected: attempt.expected.clone(),
    observed: cas_head_as_readable(h.clone(), v.clone()),
})
    },
},
})
}

#[derive(Debug, Clone, PartialEq, serde::Serialize, serde::Deserialize)]
pub struct CasGenerationReclaimFailure {
    pub generation: CasGeneration,
    pub host_error: String,
}

#[derive(Debug, Clone, PartialEq, serde::Serialize, serde::Deserialize)]
pub struct CasGenerationDeleteAttempt {
    pub generation: CasGeneration,
    pub success: bool,
    pub error: String,
}

#[derive(Debug, Clone, PartialEq, serde::Serialize, serde::Deserialize)]
#[serde(tag = "_variant")]
pub enum CasWindowReclamation {
    CasReclamationNotDeclared,
    CasReclamationNotCommitted,
    CasReclaimed {
        removed: Rc<Vec<CasGeneration>>,
    },
    CasReclamationIncomplete {
        removed: Rc<Vec<CasGeneration>>,
        failed: Rc<Vec<Rc<CasGenerationReclaimFailure>>>,
    },
    CasReclamationUnlisted {
        cause: String,
    },
}

#[derive(Debug, Clone, PartialEq, serde::Serialize, serde::Deserialize)]
pub struct CasFileWrite {
    pub outcome: Rc<CasOutcome<NonEmptyStr>>,
    pub reclamation: Rc<CasWindowReclamation>,
}

#[derive(Debug, Clone, PartialEq, serde::Serialize, serde::Deserialize)]
pub struct CasReclaimProgress {
    pub removed: Rc<Vec<CasGeneration>>,
    pub failed: Rc<Vec<Rc<CasGenerationReclaimFailure>>>,
}

pub async fn cas_reclaim_below(root: String, key: String, window: CasGenerationWindow, head: i64, filesystem: &Filesystem) -> std::result::Result<Rc<CasWindowReclamation>, std::boxed::Box<dyn std::error::Error>> {
    Ok(match (*cas_window_generations(root.clone(), key.clone(), filesystem).await?).clone() {
    CasWindowGenerations::CasWindowGenerationsUnlisted { cause: c, .. } => Rc::new(CasWindowReclamation::CasReclamationUnlisted {
    cause: c.clone(),
}),
    CasWindowGenerations::CasWindowGenerationsListed { generations: gs, .. } => {
        let floor = v1_rt::int_sub(crate::std_durable_compare_and_set::cas_generation_count(head), window.k());
let ordered = Rc::new({ let mut __keyed: Vec<_> = Rc::new({ let mut __result = Vec::new(); for g in gs.iter().cloned() { if (crate::std_durable_compare_and_set::cas_generation_count(g.clone()) <= floor.clone()) { __result.push(g); } } __result }).iter().cloned().map(|__e: i64| { let __k = (|g: i64| crate::std_durable_compare_and_set::cas_generation_count(g.clone()))(__e.clone()); (__k, __e) }).collect(); __keyed.sort_by(|__x, __y| v1_rt::canonical_key_cmp(&__x.0, &__y.0)); __keyed.into_iter().map(|(_, __e)| __e).collect::<Vec<_>>() });
let walk = { let mut __fold_acc: Rc<CasReclaimProgress> = Rc::new(CasReclaimProgress {
    removed: Rc::new(vec![]),
    failed: Rc::new(vec![]),
}); for __fold_elem in ordered.iter().cloned() { let acc = __fold_acc; let g = __fold_elem; __fold_acc = { if ((acc.failed.clone().len() as i64) != 0) {
            acc.clone()
        } else {
            {
                let d = filesystem.delete(cas_file_slot_path(root.clone(), key.clone(), g.clone())).await?;
if d.0.clone() {
                    Rc::new(CasReclaimProgress {
    removed: v1_rt::rc_list_push(acc.removed.clone(), g.clone()),
    failed: acc.failed.clone(),
})
                } else {
                    Rc::new(CasReclaimProgress {
    removed: acc.removed.clone(),
    failed: Rc::new(vec![Rc::new(CasGenerationReclaimFailure {
    generation: g.clone(),
    host_error: d.1.clone(),
})]),
})
                }
}
        } }; } __fold_acc };
if ((walk.failed.clone().len() as i64) == 0) {
            Rc::new(CasWindowReclamation::CasReclaimed {
    removed: walk.removed.clone(),
})
        } else {
            Rc::new(CasWindowReclamation::CasReclamationIncomplete {
    removed: walk.removed.clone(),
    failed: walk.failed.clone(),
})
        }
},
})
}

pub async fn file_compare_and_set_retained(root: String, publication: Rc<CasGenerationPublication>, retention: Rc<CasSlotRetention>, verified: Rc<VerifiedCasAttempt>, filesystem: &Filesystem) -> std::result::Result<Rc<CasFileWrite>, std::boxed::Box<dyn std::error::Error>> {
    let outcome = cas_compare_and_set_outcome(root.clone(), publication, retention.clone(), verified.clone(), filesystem).await?;
Ok(match (*retention.clone()).clone() {
    CasSlotRetention::KeepAllGenerations => Rc::new(CasFileWrite {
    outcome: outcome.clone(),
    reclamation: Rc::new(CasWindowReclamation::CasReclamationNotDeclared),
}),
    CasSlotRetention::KeepGenerationWindow { window: w, .. } => match (*outcome.clone()).clone() {
    CasOutcome::CasCommitted { committed: v, .. } => Rc::new(CasFileWrite {
    outcome: outcome.clone(),
    reclamation: cas_reclaim_below(root.clone(), verified.attempt().key.clone(), w.clone(), v.generation.clone(), filesystem).await?,
}),
    CasOutcome::CasPreconditionFailed { .. } => Rc::new(CasFileWrite {
    outcome: outcome.clone(),
    reclamation: Rc::new(CasWindowReclamation::CasReclamationNotCommitted),
}),
    CasOutcome::CasStoreRefused { cause: _, .. } => Rc::new(CasFileWrite {
    outcome: outcome.clone(),
    reclamation: Rc::new(CasWindowReclamation::CasReclamationNotCommitted),
}),
},
})
}

pub async fn file_compare_and_set(root: String, publication: Rc<CasGenerationPublication>, verified: Rc<VerifiedCasAttempt>, filesystem: &Filesystem) -> std::result::Result<Rc<CasOutcome<String>>, std::boxed::Box<dyn std::error::Error>> {
    Ok(file_compare_and_set_retained(root, publication, Rc::new(CasSlotRetention::KeepAllGenerations), verified, filesystem).await?.outcome.clone())
}

pub async fn file_compare_and_set_windowed(root: String, publication: Rc<CasGenerationPublication>, verified: Rc<VerifiedCasAttempt>, window: CasGenerationWindow, filesystem: &Filesystem) -> std::result::Result<Rc<CasFileWrite>, std::boxed::Box<dyn std::error::Error>> {
    Ok(file_compare_and_set_retained(root, publication, Rc::new(CasSlotRetention::KeepGenerationWindow {
    window: window.clone(),
}), verified, filesystem).await?)
}

#[derive(Debug, Clone, PartialEq, serde::Serialize, serde::Deserialize)]
#[serde(tag = "_variant")]
pub enum CasSlotKeys {
    CasSlotKeysListed {
        keys: Rc<Vec<NonEmptyStr>>,
    },
    CasSlotKeysAbsent {
        root: NonEmptyStr,
    },
    CasSlotKeysListingRefused {
        root: NonEmptyStr,
        detail: String,
    },
    CasSlotKeysSubjectRefused {
        root: NonEmptyStr,
        cause: String,
    },
}

pub fn cas_name_is_digits(s: String) -> bool {
    ((s.clone() != "".to_string()) && crate::std_decimal::decimal_digits_only(s.clone()))
}

pub fn cas_key_of_slot_name(name: String) -> Option<String> {
    {
        let parts = Rc::new(name.clone().split(&".".to_string()).map(|s| s.to_string()).collect::<Vec<_>>());
if ((parts.clone().len() as i64) < 2) {
            std::option::Option::None
        } else {
            {
                let last = match crate::std_algebra::skip(parts.clone(), v1_rt::int_sub((parts.clone().len() as i64), 1)).first().cloned() {
    std::option::Option::None => "".to_string(),
    Some(p) => p.clone(),
};
if !cas_name_is_digits(last) {
                    std::option::Option::None
                } else {
                    {
                        let key = Rc::new(v1_rt::list_take(&parts.clone(), v1_rt::int_sub((parts.clone().len() as i64), 1))).join(&".".to_string());
if (key.clone() == "".to_string()) {
                            std::option::Option::None
                        } else {
                            Some(key.clone())
                        }
}
                }
}
        }
}
}

pub async fn cas_slot_keys(root: String, filesystem: &Filesystem) -> std::result::Result<Rc<CasSlotKeys>, std::boxed::Box<dyn std::error::Error>> {
    let listing = filesystem.list(root.clone()).await?;
Ok(match (*crate::extdeps_filesystem_filesystem_io::filesystem_listing_observation(root.clone(), listing.1.clone(), listing.0.clone(), listing.2.clone())).clone() {
    FilesystemListingObservation::FilesystemDirectorySubjectRefused { cause: c, .. } => Rc::new(CasSlotKeys::CasSlotKeysSubjectRefused {
    root: root.clone(),
    cause: c.clone(),
}),
    FilesystemListingObservation::FilesystemDirectoryListingRefused { error: e, .. } => match (*crate::extdeps_filesystem_filesystem_io::filesystem_listing_absence(root.clone(), e.clone(), listing.3.clone())).clone() {
    FilesystemListingAbsence::FilesystemDirectoryListingAbsent { directory: _, .. } => Rc::new(CasSlotKeys::CasSlotKeysAbsent {
    root: root.clone(),
}),
    FilesystemListingAbsence::FilesystemDirectoryListingUnreadable { error: err, error_kind: kind, .. } => Rc::new(CasSlotKeys::CasSlotKeysListingRefused {
    root: root.clone(),
    detail: Rc::new(vec!["the directory is there but could not be read (error_kind ".to_string(), kind.clone(), "): ".to_string(), err.clone()]).join(&"".to_string()),
}),
},
    FilesystemListingObservation::FilesystemDirectoryListed(listed) => {
        let keys = crate::extdeps_filesystem_filesystem_io::filesystem_listing_entry_names(listed.clone()).iter().cloned().fold(Rc::new(vec![]), |acc: Rc<Vec<String>>, n: String| match cas_key_of_slot_name(v1_rt::trim(n.clone())) {
    std::option::Option::None => acc.clone(),
    Some(k) => v1_rt::rc_list_push(acc.clone(), k.clone()),
});
Rc::new(CasSlotKeys::CasSlotKeysListed {
    keys: crate::std_list::distinct_by_key(keys, |k| k.clone()),
})
},
})
}

