#[derive(Debug, Clone, PartialEq, serde::Serialize, serde::Deserialize)]
#[serde(tag = "_variant")]
pub enum SlotStoreAdmission {
    SlotStoreListed {
        root: NonEmptyStr,
    },
    SlotStoreAbsent {
        member: String,
        root: NonEmptyStr,
    },
    SlotStoreRefused {
        detail: String,
    },
}

pub async fn listed_slot_store(member: String, root: String, filesystem: &Filesystem) -> std::result::Result<Rc<SlotStoreAdmission>, std::boxed::Box<dyn std::error::Error>> {
    let listing = filesystem.list(root.clone()).await?;
Ok(match (*crate::extdeps_filesystem_filesystem_io::filesystem_listing_observation(root.clone(), listing.1.clone(), listing.0.clone(), listing.2.clone())).clone() {
    FilesystemListingObservation::FilesystemDirectorySubjectRefused { cause: c, .. } => Rc::new(SlotStoreAdmission::SlotStoreRefused {
    detail: Rc::new(vec!["the ".to_string(), member.clone(), " store's directory is not admissible: ".to_string(), c.clone()]).join(&"".to_string()),
}),
    FilesystemListingObservation::FilesystemDirectoryListingRefused { error: e, .. } => match (*crate::extdeps_filesystem_filesystem_io::filesystem_listing_absence(root.clone(), e.clone(), listing.3.clone())).clone() {
    FilesystemListingAbsence::FilesystemDirectoryListingAbsent { directory: _, .. } => Rc::new(SlotStoreAdmission::SlotStoreAbsent {
    member: member.clone(),
    root: root.clone(),
}),
    FilesystemListingAbsence::FilesystemDirectoryListingUnreadable { error: err, error_kind: kind, .. } => Rc::new(SlotStoreAdmission::SlotStoreRefused {
    detail: Rc::new(vec!["the ".to_string(), member.clone(), " store's directory exists but could not be read (error_kind ".to_string(), kind.clone(), "): ".to_string(), err.clone()]).join(&"".to_string()),
}),
},
    FilesystemListingObservation::FilesystemDirectoryListed(_) => Rc::new(SlotStoreAdmission::SlotStoreListed {
    root: root.clone(),
}),
})
}

pub fn slot_store_absent_detail(member: String, root: String) -> String {
    Rc::new(vec!["the ".to_string(), member.clone(), " store's own directory was never created at ".to_string(), root.clone(), " -- admission answers absence, and an absent store is not an empty store".to_string()]).join(&"".to_string())
}
